// EDUVERSE chunk: E — generated by build-split.js from canonical bank files. Do not hand-edit.
window.EDUVERSE_BANK_E = [{"bahas":"Arsitek menghasilkan denah sebagai rancangan tertulis yang menjadi panduan pembangunan, sama seperti komponis menghasilkan partitur sebagai rancangan tertulis yang menjadi panduan pertunjukan musik. Pasangan lain menunjukkan hubungan orang dengan tempat beraktivitas atau orang dengan kendaraan yang dipakai, bukan hubungan pencipta dengan rancangan tertulis yang dihasilkannya.","id":"EPU01","kunci":1,"opsi":["Penyanyi : Panggung","Komponis : Partitur","Nelayan : Perahu","Pelari : Lintasan","Guru : Kelas"],"soal":"Perhatikan pasangan kata Arsitek : Denah. Manakah pasangan kata yang memiliki hubungan yang sama dengannya?","subtes":"Penalaran Umum"},{"bahas":"Semua peserta lokakarya memakai celemek pelindung, dan semua anggota kelompok pemula termasuk peserta lokakarya, sehingga semua anggota kelompok pemula memakai celemek pelindung. Pernyataan lain bertentangan dengan premis atau membalik hubungan yang dinyatakan premis.","id":"EPU02","kunci":3,"opsi":["Sebagian anggota kelompok pemula tidak memakai celemek pelindung.","Semua orang yang memakai celemek pelindung adalah anggota kelompok pemula.","Tidak ada peserta lokakarya keramik yang merupakan anggota kelompok pemula.","Semua anggota kelompok pemula memakai celemek pelindung.","Sebagian peserta lokakarya keramik tidak memakai celemek pelindung."],"soal":"Perhatikan dua premis berikut. Premis 1: Semua peserta lokakarya keramik memakai celemek pelindung. Premis 2: Semua anggota kelompok pemula adalah peserta lokakarya keramik. Manakah kesimpulan yang tepat berdasarkan kedua premis tersebut?","subtes":"Penalaran Umum"},{"bahas":"Joko menempati kursi 5. Hana dan Galih membentuk pasangan berurutan dengan Hana di kiri Galih, sedangkan Farah harus berada di kiri Hana. Susunan yang memenuhi semua syarat hanya Farah-Hana-Galih-Irfan-Joko dan Farah-Irfan-Hana-Galih-Joko. Pada semua susunan yang memenuhi syarat, Farah selalu menempati kursi paling kiri, sedangkan posisi Hana, Galih, dan Irfan dapat berubah.","id":"EPU03","kunci":0,"opsi":["Farah duduk di kursi paling kiri.","Hana duduk di kursi kedua dari kiri.","Galih duduk di kursi ketiga dari kiri.","Irfan duduk tepat di sebelah kanan Galih.","Irfan duduk di kursi kedua dari kiri."],"soal":"Lima relawan, yaitu Farah, Galih, Hana, Irfan, dan Joko, duduk berjajar pada kursi 1 (paling kiri) sampai kursi 5 (paling kanan) saat rapat persiapan kegiatan. Diketahui: Hana duduk tepat di sebelah kiri Galih; Farah duduk di suatu tempat di sebelah kiri Hana; Joko duduk di kursi paling kanan; Irfan tidak duduk di kursi paling kiri. Manakah pernyataan yang pasti benar?","subtes":"Penalaran Umum"},{"id":"EPU04","subtes":"Penalaran Umum","soal":"Perhatikan pola bilangan berikut: 4, 7, 14, 17, 34, ... Bilangan berikutnya dalam pola tersebut adalah ...","opsi":["34","35","36","38","37"],"kunci":4,"bahas":"Pola bergantian menambah 3 lalu mengalikan 2: 4 ditambah 3 sama dengan 7, 7 dikali 2 sama dengan 14, 14 ditambah 3 sama dengan 17, dan 17 dikali 2 sama dengan 34. Langkah berikutnya adalah menambah 3, sehingga bilangan berikutnya adalah 34 ditambah 3, yaitu 37."},{"bahas":"Aturan klub mewajibkan setiap anggota yang memanjat dinding tinggi memakai helm dan didampingi pemandu. Dedi memanjat dinding tinggi, sehingga syarat tersebut berlaku untuk Dedi. Hal lain seperti waktu bergabung, jumlah pendakian, keberhasilan menyelesaikan jalur, atau pemakaian fasilitas lain tidak dinyatakan dalam informasi yang diberikan.","id":"EPU05","kunci":2,"opsi":["Dedi adalah anggota klub yang baru bergabung pada bulan ini.","Dedi memanjat dinding tinggi lebih dari satu kali pada hari ini.","Dedi memakai helm dan didampingi pemandu.","Dedi akan menyelesaikan seluruh jalur panjat tanpa berhenti.","Dedi hari ini hanya memanjat dinding tinggi dan tidak memakai fasilitas lain."],"soal":"Di sebuah klub panjat tebing dalam ruangan berlaku aturan: setiap anggota yang memanjat dinding tinggi harus memakai helm dan didampingi pemandu. Hari ini Dedi memanjat dinding tinggi di klub tersebut. Manakah kesimpulan yang pasti benar?","subtes":"Penalaran Umum"},{"bahas":"Nama tempat yang merupakan nama diri dan nama hari ditulis dengan huruf kapital, sedangkan kata umum ditulis dengan huruf kecil. Hanya kalimat tentang kunjungan ke Museum Nasional pada hari Rabu yang mengikuti kaidah tersebut; kalimat lain menulis nama diri dengan huruf kecil atau menulis kata umum dengan huruf kapital.","id":"EPPU01","kunci":4,"opsi":["Mereka berlibur ke pantai parangtritis pada bulan agustus.","Ayah bekerja di Kantor pos setiap hari senin.","Upacara bendera diadakan setiap hari Senin di Lapangan sekolah.","Siswa kelas Tujuh mengunjungi museum nasional pada hari rabu.","Mereka mengunjungi Museum Nasional pada hari Rabu."],"soal":"Kalimat manakah di bawah ini yang penulisan huruf kapitalnya sesuai dengan EYD Edisi Kelima?","subtes":"Pengetahuan dan Pemahaman Umum"},{"id":"EPPU02","subtes":"Pengetahuan dan Pemahaman Umum","soal":"Warga dari berbagai suku dan agama bekerja bersama membersihkan lingkungan kampung tanpa membedakan asal-usul. Sikap tersebut merupakan pengamalan sila Pancasila yang berbunyi ...","opsi":["Persatuan Indonesia","Ketuhanan Yang Maha Esa","Kemanusiaan yang adil dan beradab","Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan","Keadilan sosial bagi seluruh rakyat Indonesia"],"kunci":0,"bahas":"Bekerja bersama tanpa membedakan suku dan agama menunjukkan persatuan dalam keberagaman, yang merupakan pengamalan sila Persatuan Indonesia. Sila lain mengatur ketuhanan, kemanusiaan, kerakyatan, dan keadilan sosial, yang bukan penekanan utama sikap dalam pernyataan tersebut."},{"id":"EPPU03","subtes":"Pengetahuan dan Pemahaman Umum","soal":"Selat yang memisahkan Pulau Kalimantan dan Pulau Sulawesi adalah ...","opsi":["Selat Sunda","Selat Malaka","Selat Makassar","Selat Lombok","Selat Bali"],"kunci":2,"bahas":"Selat Makassar memisahkan Pulau Kalimantan di sebelah barat dan Pulau Sulawesi di sebelah timur. Selat Sunda memisahkan Pulau Sumatera dan Pulau Jawa, Selat Malaka memisahkan Pulau Sumatera dan Semenanjung Malaya, sedangkan Selat Lombok dan Selat Bali berada di antara pulau-pulau Nusa Tenggara dan Bali."},{"bahas":"Pada tekanan udara normal di permukaan laut, air murni mendidih pada suhu 100 derajat Celsius. Suhu lain tidak sesuai dengan titik didih air murni pada kondisi tersebut.","id":"EPPU04","kunci":1,"opsi":["80 derajat Celsius","100 derajat Celsius","90 derajat Celsius","120 derajat Celsius","60 derajat Celsius"],"soal":"Pada tekanan udara normal di permukaan laut, air murni mendidih pada suhu ...","subtes":"Pengetahuan dan Pemahaman Umum"},{"id":"EPPU05","subtes":"Pengetahuan dan Pemahaman Umum","soal":"Sasando, alat musik tradisional yang dimainkan dengan cara dipetik, berasal dari daerah ...","opsi":["Jawa Tengah","Bali","Sumatera Utara","Nusa Tenggara Timur","Sulawesi Selatan"],"kunci":3,"bahas":"Sasando berasal dari Pulau Rote di Nusa Tenggara Timur dan dimainkan dengan cara dipetik. Alat musik ini berbeda dari alat musik tradisional Jawa Tengah, Bali, Sumatera Utara, dan Sulawesi Selatan."},{"bahas":"Bacaan menggambarkan relawan membantu anak berlatih membaca dan berhitung, anak yang lebih besar membantu adik-adiknya, dan orang tua ikut menjaga kegiatan, lalu menyimpulkan anak mendapat dukungan belajar sedangkan warga semakin saling mengenal dan bekerja sama. Gagasan tersebut merangkum seluruh isi bacaan. Gagasan tentang kebutuhan relawan, kewajiban anak yang lebih besar, perubahan balai warga, atau air minum hanya mencakup sebagian isi atau menambahkan gagasan yang tidak dinyatakan.","id":"EPBM01","kunci":2,"opsi":["Mahasiswa dan pekerja muda membutuhkan kegiatan baru untuk mengisi waktu sore mereka.","Anak yang lebih besar harus selalu membantu adik-adiknya mengerjakan tugas sekolah.","Sanggar belajar sore memberi dukungan belajar bagi anak dan mempererat kerja sama warga.","Balai warga sebaiknya diubah menjadi tempat belajar permanen di semua lingkungan.","Orang tua bertanggung jawab menyediakan air minum bagi semua kegiatan anak."],"soal":"Setiap sore, balai warga di ujung gang berubah menjadi sanggar belajar. Para relawan, yang sebagian besar adalah mahasiswa dan pekerja muda, membantu anak-anak mengerjakan tugas sekolah dan berlatih membaca dengan cara yang menyenangkan. Anak yang lebih besar membantu adik-adiknya memahami soal, sementara relawan menyiapkan permainan berhitung dan kuis kata sederhana. Orang tua bergiliran menjaga ketertiban dan menyediakan air minum untuk semua yang hadir. Kegiatan ini tidak memungut biaya dan terbuka bagi anak mana pun di lingkungan itu. Melalui sanggar tersebut, anak-anak mendapat dukungan belajar, sedangkan warga semakin saling mengenal dan bekerja sama. Gagasan utama bacaan tersebut adalah ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Bacaan menyatakan anak mengamati, mencatat, dan menceritakan temuan, pembimbing mengajukan pertanyaan lanjutan, dan setelah tiga bulan banyak anak datang dengan pertanyaan sendiri serta lebih berani menjelaskan pengamatan. Rangkaian tersebut menunjukkan percobaan sederhana dan pertanyaan lanjutan membantu anak belajar mengamati, bertanya, dan menjelaskan temuannya. Bacaan tidak menyatakan semua anak menguasai seluruh gejala sains, tidak mengutamakan bahan tertentu, tidak menganjurkan jawaban langsung, dan tidak membatasi manfaat pada anak yang sudah berani berbicara.","id":"EPBM02","kunci":0,"opsi":["Percobaan sederhana dan pertanyaan lanjutan membantu anak belajar mengamati, bertanya, dan menjelaskan temuannya.","Semua anak kini mampu menjelaskan seluruh gejala sains dengan benar tanpa bantuan pembimbing.","Magnet dan minyak merupakan bahan terpenting dalam semua percobaan sains untuk anak.","Pembimbing sebaiknya selalu memberi jawaban langsung agar anak tidak keliru.","Kegiatan sains hanya bermanfaat bagi anak yang sudah berani berbicara di depan kelompok."],"soal":"Di sebuah pusat kegiatan anak, setiap Sabtu pagi diadakan percobaan sains sederhana. Anak-anak mengamati bayangan benda yang berubah ketika lampu digeser, mencoba magnet pada berbagai benda, dan mencampur air dengan minyak untuk melihat lapisan yang terbentuk. Setiap anak mencatat apa yang dilihatnya dalam buku kecil, lalu menceritakan temuannya kepada teman sekelompok. Pembimbing tidak langsung memberi jawaban, melainkan mengajukan pertanyaan lanjutan yang mendorong anak mencoba lagi dengan cara berbeda. Setelah tiga bulan, banyak anak datang dengan pertanyaan mereka sendiri tentang benda di sekitar rumah, dan mereka lebih berani menjelaskan hasil pengamatan dengan kata-kata sendiri. Berdasarkan bacaan tersebut, dapat disimpulkan bahwa ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Dalam konteks bacaan, permainan tradisional hampir tidak lagi dikenal, lalu didokumentasikan dan dimainkan lagi oleh anak-anak di lapangan tanpa mengubah aturan dasarnya. Makna tersebut sesuai dengan membuat permainan lama dikenal dan dimainkan lagi. Makna menciptakan permainan baru, mengubah aturan dasar, hanya menyimpan catatan, atau hanya mengajarkan kepada warga lanjut usia tidak sesuai dengan isi bacaan.","id":"EPBM03","kunci":4,"opsi":["menciptakan permainan yang sepenuhnya baru untuk menggantikan permainan lama","mengubah aturan dasar permainan lama agar sesuai dengan kebiasaan masa kini","menyimpan catatan permainan lama di balai warga tanpa memainkannya lagi","mengajarkan permainan lama hanya kepada warga lanjut usia yang sudah mengenalnya","membuat permainan lama dikenal dan dimainkan lagi oleh anak-anak"],"soal":"Di sebuah kelurahan, sekelompok pemuda mendokumentasikan permainan tradisional yang hampir tidak lagi dikenal anak-anak. Mereka mewawancarai warga lanjut usia tentang aturan main, menuliskan aturan itu dalam buku kecil, dan mengajak anak-anak mempraktikkannya di lapangan setiap akhir pekan. Permainan seperti lompat tali, congklak, dan petak umpet kembali dimainkan dengan gembira, sementara warga lanjut usia merasa pengalaman mereka dihargai. Upaya ini menghidupkan kembali permainan tradisional tanpa mengubah aturan dasarnya, sekaligus memberi anak kegiatan bersama yang tidak bergantung pada gawai. Para pemuda berharap catatan itu disimpan di balai warga agar dapat dibaca kapan saja. Frasa 'menghidupkan kembali' dalam bacaan tersebut bermakna ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Kalimat terakhir mengulang kata pameran dan kata menarik, menggabungkan penanda sangat dan sekali, serta mengulang gagasan pengunjung yang senang. Kalimat yang efektif menyampaikan gagasan yang sama secara ringkas dengan susunan yang jelas, tanpa pengulangan kata dan tanpa penanda penguat ganda: pameran menampilkan foto-foto menarik yang membuat pengunjung senang. Susunan lain masih mempertahankan pengulangan kata, penguat ganda, atau pengulangan gagasan sehingga tetap bertele-tele.","id":"EPBM04","kunci":3,"opsi":["Pameran ini sangat menarik sekali karena pameran ini sangat menarik dan pengunjung sangat senang sekali melihat foto-foto yang menarik tersebut.","Pameran yang sangat menarik sekali ini adalah pameran yang menampilkan foto-foto menarik dan pengunjung yang senang melihat foto-foto yang menarik.","Pameran ini menampilkan foto-foto yang menarik dan pengunjung-pengunjung menjadi sangat senang sekali karena foto-foto yang menarik tersebut sangat menarik.","Pameran ini menampilkan foto-foto menarik yang membuat pengunjung senang.","Pameran ini adalah pameran yang menarik karena foto-foto yang menarik membuat pengunjung-pengunjung menjadi senang melihat foto-foto yang menarik tersebut."],"soal":"Klub fotografi di sebuah sekolah menengah mengadakan pameran foto selama satu minggu. Anggota klub memotret kegiatan warga di sekitar sekolah, memilih foto terbaik, dan menulis keterangan singkat untuk setiap karya. Guru pembimbing menjelaskan cara menyusun foto agar cerita di baliknya mudah dipahami pengunjung. Setiap sore, anggota klub bergiliran menjaga ruang pameran dan menjawab pertanyaan pengunjung. Pengunjung dapat menulis tanggapan pada kartu yang disediakan di dekat pintu masuk. Pameran ini adalah pameran yang sangat menarik sekali karena pameran ini menampilkan foto-foto yang sangat menarik dan pengunjung sangat senang sekali melihat foto-foto yang menarik tersebut. Kalimat terakhir bacaan tersebut tidak efektif karena bertele-tele. Perbaikan kalimat yang paling efektif adalah ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Kata sapaan yang diikuti nama orang ditulis dengan huruf kapital sehingga bentuk yang tepat adalah Ibu Sari. Nama tempat yang merupakan nama diri ditulis dengan huruf kapital sehingga bentuk yang tepat adalah Puskesmas Melati. Kata depan di yang menyatakan tempat ditulis terpisah dari kata yang mengikutinya sehingga bentuk yang tepat adalah di kantor. Nama bulan ditulis dengan huruf kapital sehingga bentuk yang tepat adalah Januari. Bentuk yang memenuhi seluruh kaidah tersebut adalah kalimat dengan Ibu Sari, Puskesmas Melati, di kantor, dan Januari.","id":"EPBM05","kunci":1,"opsi":["Kegiatan ini dipandu oleh ibu sari dari Puskesmas Melati dan dilaksanakan di kantor kelurahan pada bulan Januari.","Kegiatan ini dipandu oleh Ibu Sari dari Puskesmas Melati dan dilaksanakan di kantor kelurahan pada bulan Januari.","Kegiatan ini dipandu oleh Ibu Sari dari puskesmas melati dan dilaksanakan di kantor kelurahan pada bulan Januari.","Kegiatan ini dipandu oleh Ibu Sari dari Puskesmas Melati dan dilaksanakan dikantor kelurahan pada bulan Januari.","Kegiatan ini dipandu oleh Ibu Sari dari Puskesmas Melati dan dilaksanakan di kantor kelurahan pada bulan januari."],"soal":"(1) Posyandu Anggrek mengadakan penyuluhan gizi untuk para ibu di lingkungan kelurahan. (2) Penyuluhan ini bertujuan membantu ibu memahami pola makan seimbang bagi balita serta mengenali tanda anak yang membutuhkan perhatian gizi lebih lanjut. (3) Kegiatan ini dipandu oleh ibu sari dari puskesmas melati dan dilaksanakan dikantor kelurahan pada bulan januari. (4) Peserta belajar menyusun menu sederhana dari bahan pangan setempat yang mudah diperoleh di pasar dan di pekarangan rumah mereka. (5) Di akhir kegiatan, peserta menerima lembar panduan bergambar dan dapat bertanya langsung kepada pemandu tentang menu untuk anak mereka di rumah. Perbaikan kalimat (3) sesuai EYD Edisi Kelima adalah ...","subtes":"Pemahaman Bacaan dan Menulis"},{"bahas":"Pemakaian pagi hari adalah 25% dari 800 liter, yaitu 200 liter, sehingga sisa air menjadi 600 liter. Pemakaian siang hari adalah 20% dari 600 liter, yaitu 120 liter, sehingga sisa air menjadi 600 liter dikurangi 120 liter, yaitu 480 liter. Persen tahap siang dihitung dari sisa air, bukan dari isi awal tangki, sehingga total pemakaian bukan 45% dari isi awal.","id":"EPK01","kunci":0,"opsi":["480 liter","440 liter","400 liter","500 liter","520 liter"],"soal":"Sebuah tangki berisi 800 liter air. Sebanyak 25% air dipakai pada pagi hari, kemudian 20% dari sisa air dipakai pada siang hari. Berapa liter air yang tersisa di dalam tangki?","subtes":"Pengetahuan Kuantitatif"},{"bahas":"Selisih perbandingan adalah 5 dikurangi 3, yaitu 2 bagian, dan selisih tersebut setara dengan 16 meter sehingga satu bagian setara dengan 8 meter. Jumlah perbandingan adalah 5 ditambah 3, yaitu 8 bagian, sehingga jumlah panjang adalah 8 dikali 8 meter, yaitu 64 meter. Sebagai pemeriksaan, panjang tali yang lebih panjang adalah 40 meter dan panjang tali yang lebih pendek adalah 24 meter, dengan selisih 16 meter.","id":"EPK02","kunci":4,"opsi":["48 meter","56 meter","60 meter","52 meter","64 meter"],"soal":"Perbandingan panjang dua potong tali adalah 5 : 3. Selisih panjang kedua tali tersebut adalah 16 meter. Berapa jumlah panjang kedua tali tersebut?","subtes":"Pengetahuan Kuantitatif"},{"id":"EPK03","subtes":"Pengetahuan Kuantitatif","soal":"Perhatikan barisan bilangan berikut: 2, 5, 14, 41, 122, ... Bilangan berikutnya dalam barisan tersebut adalah ...","opsi":["359","365","371","362","368"],"kunci":1,"bahas":"Selisih antarbilangan yang berurutan adalah 3, 9, 27, dan 81, sehingga setiap selisih merupakan tiga kali selisih sebelumnya. Selisih berikutnya adalah 243 sehingga bilangan berikutnya adalah 122 ditambah 243, yaitu 365."},{"bahas":"Luas lingkaran dihitung dengan pi dikali kuadrat jari-jari. Dengan pi 22/7 dan jari-jari 7 cm, luasnya adalah 22/7 dikali 49, yaitu 22 dikali 7, yaitu 154 cm².","id":"EPK04","kunci":3,"opsi":["140 cm²","144 cm²","150 cm²","154 cm²","158 cm²"],"soal":"Sebuah roda mainan berbentuk lingkaran memiliki jari-jari 7 cm. Jika nilai pi yang digunakan adalah 22/7, berapa luas lingkaran tersebut?","subtes":"Pengetahuan Kuantitatif"},{"bahas":"Jumlah tinggi kelima bibit adalah 12 + 15 + 14 + 17 + 12 = 70 cm. Rata-rata tinggi satu bibit diperoleh dengan membagi 70 cm dengan 5, yaitu 14 cm.","id":"EPK05","kunci":2,"opsi":["12 cm","13 cm","14 cm","15 cm","16 cm"],"soal":"Tinggi lima bibit tanaman yang diukur pada minggu yang sama berturut-turut adalah 12 cm, 15 cm, 14 cm, 17 cm, dan 12 cm. Berapa rata-rata tinggi satu bibit tanaman tersebut?","subtes":"Pengetahuan Kuantitatif"},{"bahas":"Teks membahas warga mengolah sisa dapur dan daun kering menjadi kompos, memakai pupuk itu untuk tanaman, dan jumlah sampah yang dibuang berkurang. Gagasan utamanya mencakup pengolahan sisa bahan menjadi sesuatu yang bermanfaat dan pengurangan sampah, bukan hanya satu rincian proses, satu sifat pupuk, atau anjuran yang tidak dinyatakan dalam teks.","id":"ELBI01","kunci":3,"opsi":["Daun kering dan sisa sayuran harus dikumpulkan dalam wadah tertutup setiap hari.","Pupuk berwarna gelap tidak berbau menyengat setelah bahan diolah selama beberapa minggu.","Warga di lingkungan padat perlu mengurangi jumlah sampah yang mereka buang setiap minggu.","Sisa dapur dan daun kering dapat diolah menjadi kompos yang bermanfaat dan mengurangi sampah.","Pot-pot di depan rumah sebaiknya diisi tanaman agar lingkungan terlihat lebih hijau."],"soal":"Di sebuah lingkungan padat, sekelompok warga belajar membuat kompos dari sisa dapur dan daun kering. Sisa sayuran, kulit buah, dan daun yang gugur dikumpulkan dalam wadah tertutup, lalu dibolak-balik secara teratur agar proses penguraian berjalan baik. Setelah beberapa minggu, bahan-bahan itu berubah menjadi pupuk berwarna gelap yang tidak berbau menyengat. Pupuk tersebut dipakai untuk tanaman di pekarangan dan pot-pot di depan rumah. Jumlah sampah yang dibuang warga berkurang, dan tanaman tumbuh lebih subur tanpa pupuk buatan. Kegiatan ini menunjukkan bahwa sisa bahan yang dianggap tidak berguna masih dapat diolah menjadi sesuatu yang bermanfaat bagi lingkungan sekitar. Apa gagasan utama teks tersebut?","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Teks menyatakan nelayan menggabungkan pengamatan tanda alam dengan informasi cuaca dari radio, menunda keberangkatan saat angin kencang dan gelombang tinggi, serta mencatat hasil tangkapan bersama kondisi cuaca untuk dibaca kembali sebelum perjalanan berikutnya. Teks tidak menyatakan nelayan selalu melaut, tidak menyatakan warna langit menentukan hasil tangkapan, dan tidak membatasi pencatatan pada perjalanan dengan tangkapan banyak.","id":"ELBI02","kunci":1,"opsi":["Nelayan selalu melaut setiap pagi selama bekal sudah disiapkan, apa pun kondisi angin dan gelombang.","Keputusan melaut didasarkan pada tanda alam, informasi cuaca dari radio, dan catatan pengalaman sebelumnya.","Warna langit menjelang fajar sudah cukup untuk menentukan hasil tangkapan pada hari itu.","Semua nelayan di desa itu tidak pernah menunda keberangkatan apa pun yang terjadi.","Catatan hasil tangkapan hanya dibuat untuk perjalanan yang menghasilkan tangkapan banyak."],"soal":"Para nelayan di sebuah desa pesisir menentukan waktu melaut dengan menggabungkan pengamatan tanda alam dan informasi cuaca dari radio. Warna langit menjelang fajar, arah angin, dan tinggi gelombang dibaca sebagai petunjuk kondisi laut, lalu dibandingkan dengan informasi yang disiarkan setiap pagi. Jika angin bertiup kencang dan gelombang tinggi, mereka menunda keberangkatan meskipun persediaan bekal sudah disiapkan. Setelah kembali, hasil tangkapan dicatat bersama kondisi cuaca hari itu agar pengalaman setiap perjalanan tidak hilang begitu saja. Catatan itu dibaca kembali sebelum perjalanan berikutnya, sehingga keputusan melaut bertumpu pada pengamatan, informasi dari radio, dan pengalaman sebelumnya. Berdasarkan teks, pernyataan manakah yang sesuai dengan isi teks?","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Teks menceritakan anak muda yang membuat film pendek hanya dengan telepon genggam dan lampu belajar, merekam ulang adegan yang gagal, dan belajar mengatur cahaya serta suara, lalu menarik simpulan bahwa keterbatasan alat tidak menghentikan mereka bercerita selama mereka mau mencoba, memperbaiki, dan bekerja sama. Cerita tersebut berfungsi sebagai contoh yang mendukung simpulan tersebut, bukan sebagai panduan teknis lengkap, perbandingan alat, ajakan meninggalkan studio, atau pembatasan pada anak muda di gang padat.","id":"ELBI03","kunci":4,"opsi":["Menjelaskan langkah teknis merekam film pendek dengan telepon genggam secara lengkap.","Membandingkan kualitas film yang dibuat dengan kamera mahal dan film yang dibuat dengan telepon genggam.","Mengajak semua remaja meninggalkan studio dan hanya memakai lampu belajar untuk setiap kegiatan.","Menunjukkan bahwa film pendek hanya dapat dibuat oleh anak muda yang tinggal di gang padat.","Menunjukkan bahwa keterbatasan alat tidak menghentikan seseorang untuk berkarya bila mau mencoba dan bekerja sama."],"soal":"Di sebuah sanggar remaja, sekelompok anak muda membuat film pendek hanya dengan telepon genggam dan lampu belajar. Mereka menulis cerita tentang kehidupan di gang mereka, berlatih dialog di teras rumah, dan merekam ulang adegan yang gagal berkali-kali. Tidak ada kamera mahal atau studio, tetapi mereka belajar mengatur cahaya dari jendela dan merekam suara saat lingkungan sedang tenang. Film pertama mereka ditonton warga di balai dan disambut tepuk tangan. Pengalaman itu menunjukkan bahwa keterbatasan alat tidak menghentikan mereka bercerita, selama mereka mau mencoba, memperbaiki, dan bekerja sama. Apa tujuan penulis menyajikan pengalaman sanggar remaja dalam teks tersebut?","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Bu Laras menyediakan air minum tanpa syarat dan mencatat kekurangan uang tanpa menagih dengan suara keras, lalu warga yang pernah dibantu sering kembali untuk berbelanja dan mengobrol, sehingga warung tidak pernah sepi meskipun ada toko yang lebih besar. Rangkaian peristiwa tersebut menyiratkan kebaikan kecil yang tulus dapat membangun kepercayaan dan kesetiaan warga, bukan ketergantungan pada satu pemberian, kebencian terhadap toko besar, rasa takut pembeli, atau kebutuhan akan pengumuman.","id":"ELBI04","kunci":0,"opsi":["Kebaikan kecil yang dilakukan dengan tulus dapat membangun kepercayaan dan kesetiaan warga.","Warung kecil hanya dapat bertahan bila pemiliknya memberikan air minum gratis setiap pagi.","Toko yang lebih besar dan lebih lengkap selalu sepi karena warga tidak menyukai toko besar.","Pembeli yang kekurangan uang harus selalu dicatat agar tidak berani kembali berbelanja.","Pengumuman tentang kebaikan pemilik warung diperlukan agar warga mau datang berbelanja."],"soal":"Bu Laras memiliki warung kecil di dekat persimpangan jalan desa. Setiap pagi, ia meletakkan kendi air minum di depan warung agar pejalan kaki yang kehausan dapat minum tanpa harus membeli apa pun. Ketika seorang pembeli kekurangan uang, Bu Laras mencatat jumlahnya di buku kecil dan tidak pernah menagih dengan suara keras. Warga yang pernah dibantu sering kembali, bukan hanya untuk berbelanja, melainkan juga untuk mengobrol dan menanyakan kabar. Warung itu tidak pernah sepi, meskipun di ujung jalan sudah berdiri toko yang lebih besar dan lebih lengkap. Bu Laras tidak pernah memasang pengumuman tentang kebaikannya, tetapi warung itu dikenal warga desa sebagai tempat singgah yang menenangkan. Apa makna tersirat dari tindakan Bu Laras dan sikap warga dalam teks tersebut?","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Teks menyatakan pendapat penolak buku fisik hanya melihat ketersediaan informasi, lalu menjelaskan layar gawai sering menampilkan pemberitahuan yang memotong konsentrasi sedangkan buku fisik mengajak pembaca bertahan pada satu teks, dan cara membaca memengaruhi pemahaman. Kelemahannya terletak pada cara menilai yang hanya melihat ketersediaan informasi tanpa mempertimbangkan cara membaca dan gangguan tersebut. Teks tidak membahas kebenaran informasi atau harga buku dan gawai, dan tidak menyatakan pembaca gawai tidak pernah mampu memahami hubungan antargagasan.","id":"ELBI05","kunci":2,"opsi":["Anggapan bahwa semua informasi di gawai selalu benar dan lengkap.","Keyakinan bahwa buku fisik selalu lebih murah daripada gawai.","Penilaian yang hanya melihat ketersediaan informasi tanpa mempertimbangkan cara membaca dan gangguan yang menyertainya.","Gagasan bahwa membaca dengan tenang membuat pembaca mengingat isi bacaan dengan lebih baik.","Dugaan bahwa pembaca gawai tidak pernah mampu memahami hubungan antargagasan sama sekali."],"soal":"Sebagian orang berpendapat bahwa membaca buku fisik sudah tidak lagi diperlukan karena semua informasi kini tersedia melalui gawai. Pendapat ini hanya melihat ketersediaan informasi, tanpa memperhatikan cara orang membaca dan gangguan yang menyertainya. Layar gawai sering menampilkan pemberitahuan yang memotong konsentrasi, sedangkan buku fisik mengajak pembaca bertahan pada satu teks tanpa interupsi. Membaca dengan tenang membantu pembaca memahami hubungan antargagasan dan mengingat isi bacaan dengan lebih baik. Karena itu, menilai kegiatan membaca hanya dari mudahnya memperoleh informasi adalah cara menilai yang tidak lengkap, sebab cara membaca memengaruhi apa yang dipahami pembaca. Menurut teks, kelemahan pendapat yang menganggap buku fisik tidak lagi diperlukan terletak pada ...","subtes":"Literasi Bahasa Indonesia"},{"bahas":"Teks menjelaskan jalan pagi tempat warga belajar mendengarkan kicau, memperhatikan pola bulu, dan mencatat pengamatan, lalu menyebutkan tujuannya: warga melambat, mengamati dunia di sekitar mereka, dan peduli pada ruang hijau dekat rumah. Gagasan utama mencakup seluruh tujuan tersebut, bukan hanya satu rincian atau anjuran yang tidak dinyatakan.","id":"ELBE01","kunci":1,"opsi":["Beginners should learn to recognize every bird species before joining a walk.","Bird-watching walks help residents learn about birds, observe nature closely, and care for nearby green spaces.","Retired teachers are the only people who can lead a successful bird-watching walk.","Most birds in the field look exactly alike and cannot be told apart by beginners.","A shared notebook is the most important part of any outdoor activity."],"soal":"Every Saturday morning, a small group of neighbors meets at the edge of a field to watch birds. A retired teacher leads the walk and shows participants how to listen for different calls, notice feather patterns, and record what they see in a shared notebook. Beginners often feel unsure at first because many birds look alike from a distance. After a few walks, however, they begin to recognize common species and to point out nests they had never noticed before. The organizers say the walks are not only about naming birds. They also want residents to slow down, observe the world around them, and care for the green spaces near their homes. What is the main idea of the passage?","subtes":"Literasi Bahasa Inggris"},{"bahas":"Kata tersebut menggambarkan tekanan yang diterapkan pada tanah liat saat roda berputar perlahan, berbeda dengan tekanan yang terlalu keras sehingga mangkuk runtuh, dan sejalan dengan tangan yang tenang, pengamatan yang cermat, serta koreksi kecil. Gambaran tersebut menunjukkan tekanan yang lembut dan hati-hati, bukan tekanan yang kuat, cepat, kasar, atau kaku.","id":"ELBE02","kunci":4,"opsi":["strong and forceful","fast and sudden","rough and uneven","firm and unchanging","soft and careful"],"soal":"When Ardi joined a pottery class, he expected to shape clay quickly and easily. His first bowls were uneven, and several collapsed because he pressed too hard with his hands. The instructor showed him how to center the clay, keep his hands wet, and apply gentle pressure while the wheel turned slowly. Changes appeared little by little: a smoother rim, a rounder base, then a bowl that kept its shape after drying. Ardi learned that clay responds to patience rather than force. A calm hand, careful watching, and small corrections matter more than speed when the wheel is turning. The word 'gentle' in the passage is closest in meaning to ...","subtes":"Literasi Bahasa Inggris"},{"bahas":"Teks menyatakan hanya tiga siswa mendaftar dan pembimbing meragukan klub bertahan, lalu Dina mengajari siapa pun yang berhenti menonton dan menjaga tangga sederhana, hingga lebih dari tiga puluh siswa bermain secara teratur termasuk beberapa yang belum pernah bermain, dan pembimbing meminta Dina membantu memulai klub serupa. Rangkaian fakta tersebut menunjukkan pendekatan Dina yang ramah membantu klub kecil berkembang dan mendapat dukungan untuk klub baru. Teks tidak menyatakan pembimbing mendukung sejak awal, tidak menyatakan seluruh siswa berpengalaman, tidak menyatakan sudut kantin ditutup untuk siswa lain, dan tidak menyatakan Dina memenangi setiap permainan.","id":"ELBE03","kunci":0,"opsi":["Dina's patient and welcoming approach helped a small club grow and earned support for a new club.","The teacher advisor supported the chess club enthusiastically from the very beginning.","All thirty students were experienced chess players before joining the club.","The canteen staff closed the canteen corner to all students except chess players.","Dina won every game she played and reached the top of the ladder herself."],"soal":"When Dina proposed a lunchtime chess club at her school, only three students signed up, and the teacher advisor doubted that the club would last beyond a month. Dina set up two boards near the canteen, taught the basic moves to anyone who stopped to watch, and kept a simple ladder where winners moved up one step. By the end of the term, more than thirty students were playing regularly, including several who had never played before, and the canteen staff had reserved a corner table for the club every day. The advisor now asks Dina to help start a similar club for board games at a neighboring school. What can be inferred from the passage?","subtes":"Literasi Bahasa Inggris"},{"bahas":"Teks menyatakan pengunjung boleh mengambil paket benih tanpa biaya, tetapi diminta membawa benih mereka sendiri pada tahun berikutnya agar koleksi terus bertambah. Alasan tersebut berkaitan dengan pertumbuhan koleksi benih, bukan dengan pembayaran, kecepatan benih habis, asal benih yang disimpan, atau lamanya benih herba bertahan.","id":"ELBE04","kunci":2,"opsi":["Because visitors must pay for the packets they take at the fair.","Because tomato and chili seeds always run out within an hour.","Because the organizers want the seed collection to keep growing.","Because gardeners only save seeds from the strongest plants each season.","Because herbs last until the afternoon while other seeds run out early."],"soal":"Once a year, gardeners from nearby villages gather at a seed exchange fair. Each gardener brings small packets of seeds saved from the strongest plants of the previous season, labeled with the plant name and the month the seeds were collected. Visitors may take packets for free, but they are asked to bring seeds of their own the following year so the collection keeps growing. Children help sort the packets into boxes by plant family, and older gardeners share tips about watering and sunlight. Last year, tomato and chili seeds ran out within an hour, while packets of herbs lasted until the afternoon. The organizers hope the fair will help gardeners grow plants that suit local soil and weather. According to the passage, why are visitors asked to bring seeds of their own the following year?","subtes":"Literasi Bahasa Inggris"},{"bahas":"Teks menceritakan Tono yang mulai belajar memperbaiki sepeda setelah pensiun, berkembang selangkah demi selangkah, lalu memperbaiki sepeda tetangga dan mengajari remaja, serta menilai lokakarya memberinya alasan bertemu orang, cara membantu, dan pengingat bahwa babak baru dapat dimulai setelah karier berakhir. Cerita tersebut menggambarkan nilai belajar keterampilan praktis setelah pensiun, bukan kecepatan belajar, penggantian kegiatan relawan lain, cara memilih perkakas, atau penguasaan penuh dalam beberapa bulan.","id":"ELBE05","kunci":3,"opsi":["To argue that retired clerks learn repair skills faster than teenagers in every case.","To suggest that bicycle repair workshops should replace all other volunteer activities.","To explain the best method for choosing tools for a bicycle repair workshop.","To show that learning a practical skill after retirement can bring purpose, connection, and a way to help others.","To claim that anyone can master bicycle repair completely within a few months."],"soal":"After retiring from his job as a clerk, Tono joined a bicycle repair workshop run by volunteers. At first, he could not tell a wrench from a screwdriver, and he tightened bolts so hard that several threads were damaged. The volunteers showed him how to listen for a loose chain, check tire pressure, and adjust brakes one small step at a time. Within a few months, Tono was repairing neighbors' bicycles on his porch and teaching teenagers to fix a flat tire. He says the workshop gave him more than a skill. It gave him a reason to meet people, a way to help, and a reminder that a new chapter can begin long after a career ends. What is the author's purpose in telling Tono's story?","subtes":"Literasi Bahasa Inggris"},{"bahas":"Dalam 2 jam, 3 petugas menempel 180 label, sehingga satu petugas menempel 60 label dalam 2 jam atau 30 label dalam 1 jam. Untuk 5 petugas selama 3 jam: 5 dikali 3 dikali 30 sama dengan 450 label.","id":"EPM01","kunci":2,"opsi":["400","420","450","480","540"],"soal":"Tiga petugas dengan laju kerja yang sama menempel 180 label pada kotak bantuan dalam 2 jam. Jika jumlah petugas menjadi 5 orang dan semuanya bekerja selama 3 jam dengan laju yang sama, berapa label yang ditempel?","subtes":"Penalaran Matematika"},{"id":"EPM02","subtes":"Penalaran Matematika","soal":"Perhatikan barisan bilangan berikut: 1, 2, 10, 37, 101, ... Bilangan berikutnya dalam barisan tersebut adalah ....","opsi":["218","221","224","226","229"],"kunci":3,"bahas":"Selisih antarsuku yang berurutan adalah 1, 8, 27, dan 64, yaitu pangkat tiga bilangan 1, 2, 3, dan 4. Selisih berikutnya adalah pangkat tiga 5, yaitu 125, sehingga bilangan berikutnya adalah 101 ditambah 125, yaitu 226."},{"id":"EPM03","subtes":"Penalaran Matematika","soal":"Tinggi 8 tanaman cabai dalam sentimeter tercatat sebagai berikut: 12, 15, 14, 18, 16, 15, 20, 14. Selisih antara tinggi tanaman tertinggi dan rata-rata tinggi tanaman tersebut adalah ....","opsi":["4,5","4","5","3,5","5,5"],"kunci":0,"bahas":"Jumlah tinggi kedelapan tanaman adalah 12 + 15 + 14 + 18 + 16 + 15 + 20 + 14 = 124 cm, sehingga rata-ratanya 124 : 8 = 15,5 cm. Tinggi tertinggi adalah 20 cm, sehingga selisihnya adalah 20 dikurangi 15,5, yaitu 4,5 cm."},{"id":"EPM04","subtes":"Penalaran Matematika","soal":"Sekeping uang logam yang adil dilempar tiga kali. Peluang bahwa tepat dua dari tiga lemparan tersebut menunjukkan gambar adalah ....","opsi":["1/4","1/2","3/4","5/8","3/8"],"kunci":4,"bahas":"Tiga lemparan menghasilkan delapan rangkaian hasil yang sama mungkinnya. Rangkaian dengan tepat dua gambar ada tiga: gambar-gambar-angka, gambar-angka-gambar, dan angka-gambar-gambar. Peluangnya adalah 3 dari 8, yaitu 3/8."},{"id":"EPM05","subtes":"Penalaran Matematika","soal":"Hasil panen cabai dari empat petak tercatat sebagai berikut: 80 kg, 90 kg, 100 kg, dan 90 kg. Petak kelima ditargetkan menghasilkan 20% lebih banyak daripada rata-rata hasil empat petak tersebut. Target hasil petak kelima adalah ....","opsi":["100","108","112","104","116"],"kunci":1,"bahas":"Jumlah hasil empat petak adalah 80 + 90 + 100 + 90 = 360 kg, sehingga rata-ratanya 360 : 4 = 90 kg. Hasil yang 20% lebih banyak adalah 90 ditambah 20/100 dikali 90, yaitu 90 ditambah 18, sama dengan 108 kg."}];
